sys_script_include.script:
var ReadinessScorer = Class.create();
ReadinessScorer.prototype = {

    initialize: function() {},

    calculateScore: function(assessmentSysId) {

        var totalWeight = 0;
        var earnedWeight = 0;
        var mandatoryFailure = false;

        var gr = new GlideRecord('x_1858206_sentin_0_checklist_result');
        gr.addQuery('assessment', assessmentSysId);
        gr.query();

        while (gr.next()) {

            var weight = parseInt(gr.weight, 10) || 0;
            totalWeight += weight;

            if (gr.result == 'pass') {
                earnedWeight += weight;
            }

            if (gr.is_mandatory == true && gr.result == 'fail') {
                mandatoryFailure = true;
            }
        }

        var score = 0;

        if (totalWeight > 0) {
            score = Math.round((earnedWeight / totalWeight) * 100);
        }

        return {
            score: score,
            mandatory_failure: mandatoryFailure
        };
    },

    type: 'ReadinessScorer'
};
